// Headless logic test for the brick breaker. Usage: node harness.js <path-to-index.html>
'use strict';
const fs = require('fs');
const vm = require('vm');

const html = fs.readFileSync(process.argv[2], 'utf8');
const m = html.match(/<script>([\s\S]*?)<\/script>/);
if (!m) throw new Error('no <script> found');
let src = m[1];

// Test-only hook exposing internals, injected right before the IIFE closes.
const hook = `
  globalThis.__g = {
    get state() { return state; }, get lives() { return lives; }, get score() { return score; },
    get shownScore() { return shownScore; }, get levelIndex() { return levelIndex; },
    get bricksLeft() { return bricksLeft; }, get bricks() { return bricks; },
    get best() { return best; }, get newBest() { return newBest; }, get bonusLines() { return bonusLines; },
    killAllBut(n) { for (const b of bricks.filter((b) => b.alive).slice(n)) { b.alive = false; bricksLeft--; } },
    ball, paddle, frame, W, H, HUD_H, BALL_R,
  };
`;
const end = src.lastIndexOf('})();');
src = src.slice(0, end) + hook + src.slice(end);

const listeners = {};
const on = (target) => (type, fn) => { (listeners[`${target}:${type}`] = listeners[`${target}:${type}`] || []).push(fn); };
const fire = (target, type, ev) => (listeners[`${target}:${type}`] || []).forEach((fn) => fn(ev));

// Canvas stub: every method is a no-op that rejects NaN/Infinity arguments.
let drawCalls = 0;
const gradientStub = { addColorStop(o, c) { if (!(o >= 0 && o <= 1) || typeof c !== 'string') throw new Error('bad color stop'); } };
const ctxStub = new Proxy({}, {
  get(t, p) {
    if (p === 'createLinearGradient' || p === 'createRadialGradient') return () => gradientStub;
    if (p === 'measureText') return () => ({ width: 50 });
    if (p in t) return t[p];
    return (...args) => {
      drawCalls++;
      for (const a of args) if (typeof a === 'number' && !Number.isFinite(a)) throw new Error(`non-finite arg to ${String(p)}: ${args}`);
    };
  },
  set(t, p, v) {
    if (p === 'globalAlpha' && !(v >= 0 && v <= 1)) throw new Error('bad globalAlpha ' + v);
    if ((p === 'shadowBlur' || p === 'lineWidth') && !Number.isFinite(v)) throw new Error('bad ' + p);
    t[p] = v;
    return true;
  },
});
const canvas = {
  width: 800, height: 600, style: {},
  getContext: () => ctxStub,
  getBoundingClientRect: () => ({ left: 0, top: 0, width: 800, height: 600 }),
  addEventListener: on('canvas'),
};
const storage = {};
const sandbox = {
  document: { getElementById: () => canvas, addEventListener: on('document'), hidden: false },
  localStorage: { getItem: (k) => (k in storage ? storage[k] : null), setItem: (k, v) => { storage[k] = String(v); } },
  requestAnimationFrame: () => {},
  innerWidth: 1000, innerHeight: 800, devicePixelRatio: 1.5,
  addEventListener: on('window'),
  console,
};
sandbox.window = sandbox;
vm.createContext(sandbox);
vm.runInContext(src, sandbox);
const g = sandbox.__g;

// ---- helpers ----
let now = 1000;
const tick = (n = 1, ms = 1000 / 60) => { for (let i = 0; i < n; i++) { now += ms; g.frame(now); checkInvariants(); } };
const key = (code, type = 'keydown') => fire('window', type, { code, repeat: false, preventDefault() {} });
const tap = (code) => { key(code, 'keydown'); key(code, 'keyup'); };
const move = (x) => fire('window', 'pointermove', { clientX: x });
const click = (x = g.paddle.x + g.paddle.w / 2) => fire('window', 'pointerdown', { clientX: x, button: 0 });
let failures = 0;
function assert(cond, msg) {
  if (!cond) { failures++; console.log('FAIL:', msg); }
  else console.log('ok  :', msg);
}
function checkInvariants() {
  const b = g.ball, R = g.BALL_R;
  const die = (msg) => { throw new Error(`INVARIANT (${g.state}): ${msg}`); };
  if (g.state === 'play') {
    if (!(b.x >= R - 1e-6 && b.x <= g.W - R + 1e-6)) die(`ball x out of bounds ${b.x}`);
    if (!(b.y >= g.HUD_H + R - 1e-6)) die(`ball above ceiling ${b.y}`);
    for (const br of g.bricks) {
      if (br.alive && b.x + R > br.x && b.x - R < br.x + br.w && b.y + R > br.y && b.y - R < br.y + br.h) {
        die(`ball inside brick ${br.x},${br.y}`);
      }
    }
    const sp = Math.hypot(b.vx, b.vy);
    if (Math.abs(sp - b.speed) > 1e-6) die(`speed mismatch ${sp} vs ${b.speed}`);
    if (Math.abs(b.vy) < 0.4999 * sp) die(`too horizontal vy=${b.vy} speed=${sp}`);
  }
  if (!(g.paddle.x >= 0 && g.paddle.x + g.paddle.w <= g.W + 1e-9)) die('paddle out of bounds');
}

// Mouse autopilot: keeps the paddle under the ball with a random aim offset per return.
function autopilot(maxSeconds) {
  let aimed = false, offset = 0, frames = 0, bounces = 0;
  while (g.state === 'play' && frames < maxSeconds * 60) {
    if (g.ball.vy > 0 && !aimed) { offset = (Math.random() * 2 - 1) * 0.85 * (g.paddle.w / 2); aimed = true; bounces++; }
    if (g.ball.vy < 0) aimed = false;
    move(g.ball.x - offset);
    tick();
    frames++;
  }
  return { seconds: frames / 60, bounces };
}

// ---- 1. Title screen & starting ----
tick(10);
assert(g.state === 'title', 'starts on the title screen');
assert(g.lives === 3 && g.score === 0, 'starts with 3 lives and score 0');
tap('Space');
assert(g.state === 'serve' && g.levelIndex === 0, 'Space starts level 1');
tick(5); tap('Space');
assert(g.state === 'serve', 'launch ignored during brick intro');
tick(60);

// ---- 2. Keyboard steering while serving ----
let x0 = g.paddle.x;
key('ArrowRight'); tick(15); key('ArrowRight', 'keyup');
assert(Math.abs(g.paddle.x - (x0 + 720 * 15 / 60)) < 1e-6, `ArrowRight moves paddle at 720px/s (${x0} -> ${g.paddle.x})`);
assert(Math.abs(g.ball.x - (g.paddle.x + g.paddle.w / 2)) < 1e-9, 'ball rides on the paddle while serving');
key('KeyA'); tick(120); key('KeyA', 'keyup');
assert(g.paddle.x === 0, 'A moves paddle left and clamps at the wall');
key('KeyD'); tick(200); key('KeyD', 'keyup');
assert(g.paddle.x === g.W - g.paddle.w, 'D moves paddle right and clamps at the wall');
move(400);
tick(1);
assert(g.paddle.x + g.paddle.w / 2 === 400, 'mouse move centres paddle on the pointer');

// ---- 3. Play through level 1 with the mouse ----
tap('Space');
assert(g.state === 'play', 'Space launches the ball');
let run = autopilot(1200);
assert(g.state === 'levelClear', `level 1 cleared (${run.seconds.toFixed(0)}s game time, ${run.bounces} paddle returns)`);
assert(g.lives === 3, 'no lives lost on autopilot');
assert(g.score === 2700 + 1000, `level 1 score = bricks 2700 + bonus 1000 (got ${g.score})`);
tick(60 * 3 + 2);
assert(g.state === 'serve' && g.levelIndex === 1, 'level 2 starts automatically after the clear screen');
assert(g.bricksLeft === 46 && g.paddle.w === 104, 'level 2 has 46 bricks and a narrower paddle');
assert(g.ball.speed === 420, 'level 2 ball starts faster');

// ---- 4. Play through level 2 (silver bricks need two hits) ----
tick(60);
click();
assert(g.state === 'play', 'mouse click launches the ball');
const silver = g.bricks.filter((b) => b.maxHits === 2).length;
assert(silver === 17, '17 silver bricks in level 2');
run = autopilot(1200);
assert(g.state === 'win', `level 2 cleared -> win screen (${run.seconds.toFixed(0)}s game time)`);
const expected = 3700 + (16 * 60 + 13 * 50 + 17 * 110) + 2000 + 3 * 500;
assert(g.score === expected, `final score ${g.score} === ${expected}`);
tick(90);
assert(g.shownScore === g.score, 'HUD score caught up with the real score');
assert(g.best === g.score && g.newBest && storage['brickBreaker.best'] === String(g.score), 'best score saved to localStorage');

// ---- 5. Restart and lose all 3 lives ----
tap('Space');
assert(g.state === 'serve' && g.levelIndex === 0 && g.lives === 3 && g.score === 0, 'Space on win screen restarts at level 1');
tick(60); tap('Space');
for (let life = 3; life >= 1; life--) {
  let frames = 0;
  while (g.state === 'play' && frames < 3600) { move(g.ball.x < 400 ? 790 : 10); tick(); frames++; }
  assert(g.state === 'dying' && g.lives === life - 1, `missed ball costs a life (lives now ${g.lives})`);
  tap('Space');
  assert(g.state === 'dying', 'input ignored during life-lost animation');
  tick(70);
  if (life > 1) {
    assert(g.state === 'serve', 'ball returns to the paddle');
    tap('Space');
  }
}
assert(g.state === 'gameOver', 'game over after losing 3 lives');
tap('Space');
assert(g.state === 'gameOver', 'restart blocked for the first second of game over');
tick(65); click();
assert(g.state === 'serve' && g.lives === 3, 'click restarts after game over');

// ---- 6. Pause / resume / blur / mute / resize ----
tick(60); tap('Space');
tick(20);
tap('KeyP');
assert(g.state === 'paused', 'P pauses');
const bx = g.ball.x, by = g.ball.y;
tick(120);
assert(g.ball.x === bx && g.ball.y === by, 'ball frozen while paused');
tap('Escape');
assert(g.state === 'play', 'Esc resumes');
fire('window', 'blur', {});
assert(g.state === 'paused', 'auto-pauses when the window loses focus');
click();
assert(g.state === 'play', 'click resumes');
tap('KeyM'); tick(10); tap('KeyM'); tick(100);
assert(storage['brickBreaker.muted'] === '0', 'M toggles mute (persisted)');
sandbox.innerWidth = 500; sandbox.innerHeight = 300; fire('window', 'resize', {});
tick(5);
assert(canvas.width > 0 && canvas.style.width === '368px', `resize fits the window (css ${canvas.style.width})`);

// ---- 7. Level-clear screen can be skipped with a click after 0.8s ----
g.killAllBut(1);
run = autopilot(600);
assert(g.state === 'levelClear', 'clearing the last brick shows the clear screen');
tick(20); click();
assert(g.state === 'levelClear', 'continue blocked for the first 0.8s');
tick(40); click();
assert(g.state === 'serve' && g.levelIndex === 1, 'click continues to level 2');

// ---- 8. Win with fewer lives gives a smaller lives bonus ----
tick(60); tap('Space');
while (g.state === 'play') { move(g.ball.x < 400 ? 790 : 10); tick(); }
tick(70);
assert(g.lives === 2 && g.state === 'serve', 'lost one life on level 2');
tap('Space');
g.killAllBut(1);
autopilot(600);
assert(g.state === 'win' && g.bonusLines[1].includes('2 × 500 = +1000'), `lives bonus reflects 2 lives: "${g.bonusLines[1]}"`);

console.log(`\n${failures ? failures + ' FAILURE(S)' : 'ALL CHECKS PASSED'} — ${drawCalls} draw calls, no exceptions`);
process.exit(failures ? 1 : 0);

