119	  // Mix a #rrggbb colour towards white (amount > 0) or black (amount < 0).
120	  function shade(hex, amount) {
121	    const n = parseInt(hex.slice(1), 16);
122	    const target = amount < 0 ? 0 : 255, k = Math.abs(amount);
123	    const mix = (c) => Math.round(c + (target - c) * k);
