133	  function roundRect(x, y, w, h, r) {
134	    r = Math.min(r, w / 2, h / 2);
135	    ctx.beginPath();
136	    ctx.moveTo(x + r, y);
137	    ctx.arcTo(x + w, y, x + w, y + h, r);
138	    ctx.arcTo(x + w, y + h, x, y + h, r);
139	    ctx.arcTo(x, y + h, x, y, r);
140	    ctx.arcTo(x, y, x + w, y, r);
141	    ctx.closePath();
142	  }
