178	  const sfx = (() => {
179	    let ac = null, master = null;
180	    let muted = store.get('brickBreaker.muted') === '1';
181	
182	    // Browsers only allow audio after a user gesture, so this runs on key presses / clicks.
183	    function unlock() {
184	      if (!ac) {
185	        const AudioCtx = window.AudioContext || window.webkitAudioContext;
186	        if (!AudioCtx) return;
187	        try {
188	          ac = new AudioCtx();
189	          master = ac.createGain();
190	          master.gain.value = 0.2;
191	          master.connect(ac.destination);
192	        } catch (e) {
193	          ac = null;
194	          return;
195	        }
196	      }
197	      if (ac.state === 'suspended') {
198	        const resumed = ac.resume();
199	        if (resumed && resumed.catch) resumed.catch(() => {});
200	      }
201	    }
202	
203	    function tone(freq, dur, type, vol, endFreq = 0, delay = 0) {
204	      if (muted || !ac) return;
205	      const t = ac.currentTime + delay;
206	      const osc = ac.createOscillator();
207	      const gain = ac.createGain();
208	      osc.type = type;
209	      osc.frequency.setValueAtTime(freq, t);
210	      if (endFreq) osc.frequency.exponentialRampToValueAtTime(endFreq, t + dur);
211	      gain.gain.setValueAtTime(0.0001, t);
212	      gain.gain.exponentialRampToValueAtTime(vol, t + 0.01);
213	      gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
214	      osc.connect(gain);
215	      gain.connect(master);
216	      osc.start(t);
217	      osc.stop(t + dur + 0.05);
218	    }
