238	      gameOver: () => melody([392, 330, 262, 196], 0.22, 0.32, 'triangle', 0.4),
239	      win: () => melody([523, 659, 784, 1047, 784, 1047, 1319], 0.12, 0.2, 'square', 0.25),
240	    };
