266	  function buildBricks(map) {
267	    const cols = Math.max(...map.map((row) => row.length));
268	    const bw = Math.floor((W - 2 * SIDE_MARGIN - (cols - 1) * BRICK_GAP) / cols);
269	    const left = Math.floor((W - (cols * bw + (cols - 1) * BRICK_GAP)) / 2);
270	    const list = [];
271	    map.forEach((row, r) => {
272	      [...row].forEach((ch, c) => {
273	        const type = BRICK_TYPES[ch];
274	        if (!type) return;
275	        const hits = type.hits || 1;
276	        list.push({
277	          x: left + c * (bw + BRICK_GAP),
278	          y: BRICK_TOP + r * (BRICK_H + BRICK_GAP),
279	          w: bw, h: BRICK_H,
280	          type: ch, color: type.color, points: type.points,
281	          hits, maxHits: hits, alive: true, flash: 0, crack: null,
282	          delay: r * 0.05 + Math.abs(c - (cols - 1) / 2) * 0.02,   // drop-in order: top centre first
283	        });
284	      });
285	    });
286	    return list;
287	  }
