514	  // Keyboard nudges the paddle; a mouse move jumps it straight to the pointer.
515	  function movePaddle(dt) {
516	    const dir = (rightHeld() ? 1 : 0) - (leftHeld() ? 1 : 0);
517	    paddle.x += dir * PADDLE_KEY_SPEED * dt;
518	    if (pointer.moved) {
519	      paddle.x = pointer.x - paddle.w / 2;
520	      pointer.moved = false;
521	    }
522	    paddle.x = clamp(paddle.x, 0, W - paddle.w);
523	  }
