525	  function updateBall(dt) {
526	    const steps = Math.max(1, Math.ceil((Math.hypot(ball.vx, ball.vy) * dt) / SUBSTEP));
527	    for (let i = 0; i < steps && state === 'play'; i++) stepBall(dt / steps);
528	    if (state === 'play') trail.push({ x: ball.x, y: ball.y, t: time });
529	    while (trail.length && time - trail[0].t > 0.12) trail.shift();
530	  }
531	
532	  function bricksTouchingBall() {
533	    const left = ball.x - BALL_R, right = ball.x + BALL_R;
534	    const top = ball.y - BALL_R, bottom = ball.y + BALL_R;
535	    return bricks.filter((b) => b.alive && right > b.x && left < b.x + b.w && bottom > b.y && top < b.y + b.h);
536	  }
537	
538	  // Moves the ball one small step. Each axis is moved and resolved separately, which makes it
539	  // unambiguous whether a brick was hit on its side (flip vx) or its top/bottom (flip vy).
540	  function stepBall(dt) {
541	    ball.x += ball.vx * dt;
542	    if (ball.x < BALL_R) {
543	      ball.x = BALL_R;
544	      ball.vx = Math.abs(ball.vx);
545	      sfx.wall();
546	    } else if (ball.x > W - BALL_R) {
547	      ball.x = W - BALL_R;
548	      ball.vx = -Math.abs(ball.vx);
549	      sfx.wall();
550	    }
551	    let hits = bricksTouchingBall();
552	    if (hits.length) {
553	      ball.x = ball.vx > 0
554	        ? Math.min(...hits.map((b) => b.x)) - BALL_R - 0.01
555	        : Math.max(...hits.map((b) => b.x + b.w)) + BALL_R + 0.01;
556	      ball.vx = -ball.vx;
557	      hits.forEach(hitBrick);
558	    }
559	
560	    ball.y += ball.vy * dt;
561	    if (ball.y < HUD_H + BALL_R) {
562	      ball.y = HUD_H + BALL_R;
563	      ball.vy = Math.abs(ball.vy);
564	      sfx.wall();
565	    }
566	    hits = bricksTouchingBall();
567	    if (hits.length) {
568	      ball.y = ball.vy > 0
569	        ? Math.min(...hits.map((b) => b.y)) - BALL_R - 0.01
570	        : Math.max(...hits.map((b) => b.y + b.h)) + BALL_R + 0.01;
571	      ball.vy = -ball.vy;
572	      hits.forEach(hitBrick);
573	    }
574	
575	    if (bricksLeft === 0) {
576	      levelComplete();
577	      return;
578	    }
579	
580	    // Paddle: only while falling and while the ball's centre is still above the paddle's middle.
581	    if (ball.vy > 0 &&
582	        ball.y + BALL_R > paddle.y && ball.y < paddle.y + paddle.h / 2 &&
583	        ball.x + BALL_R > paddle.x && ball.x - BALL_R < paddle.x + paddle.w) {
584	      bounceOffPaddle();
585	    }
586	
587	    if (ball.y - BALL_R > H) loseLife();
588	  }
