590	  // Where the ball lands on the paddle sets the new angle: centre = straight up, edges = 60°.
591	  function bounceOffPaddle() {
592	    const half = paddle.w / 2;
593	    const offset = clamp((ball.x - (paddle.x + half)) / (half + BALL_R / 2), -1, 1);
594	    const angle = offset * MAX_BOUNCE;
595	    ball.vx = ball.speed * Math.sin(angle);
596	    ball.vy = -ball.speed * Math.cos(angle);
597	    ball.y = paddle.y - BALL_R - 0.01;
598	    paddle.flash = 1;
599	    combo = 0;
600	    sfx.paddle();
601	  }
