603	  function hitBrick(b) {
604	    b.flash = 1;
605	    const cx = b.x + b.w / 2, cy = b.y + b.h / 2;
606	    if (--b.hits > 0) {                  // a tough brick survives this hit
607	      score += 10;
608	      if (!b.crack) b.crack = makeCrack(b.w, b.h);
609	      floaters.push({ x: cx, y: cy, text: '+10', color: '#e6ebff', life: 0.6, max: 0.6 });
610	      burst(cx, cy, ['#ffffff', '#b9c3d6'], 6, 140, b);
611	      sfx.metal();
612	      return;
613	    }
614	    b.alive = false;
615	    bricksLeft--;
616	    combo++;
617	    score += b.points;
